from __future__ import annotations

import logging
import re
from typing import Any

from .qwen3_cues import (
    _cue_text_is_echo,
    _cue_text_is_measure_shard,
    _distribute_text_cues,
    _normalize_filler_no,
    _result_text,
)
from .qwen3_constants import (
    _ISLAND_MAX_NEW_TOKENS,
    _QWEN_SR,
)
from .qwen3_infer import (
    _transcribe_audio_list,
)

_log = logging.getLogger("transub_engine.asr.qwen3_retry")

_WEAK_PARTICLE_RE = re.compile(
    r"^[はがをにでのともへやねよわをばぁアァうっんンー〜～っッ]+$"
)
_FILLER_TAIL_RE = re.compile(
    r"(えー+|あの[ーう]*|えっと|うーん+|んー+)$"
)
_DIALOGUE_RE = re.compile(
    r"(です|ます|ですか|ですね|出身|自己|紹介|じゃない|センチ|けど)"
)
_HALLU_RE = re.compile(
    r"ご視聴ありがとうございました|字幕を作成|チャンネル登録"
)
_MOAN_CHARS = set("んンぁァあアっッはぁハふフぅゥうウー〜～")
_KANJI_RE = re.compile(r"[\u4e00-\u9fff]")


# Empty / ellipsis-only breaths are not batch misses. Longer empties still
# solo-retry: padding often dropped a real line (DLDSS-553).
_EMPTY_ISLAND_SOLO_MIN_S = 0.7


def _island_transcript_looks_weak(text: str, *, span_s: float) -> bool:
    """True when batch ASR likely dropped dialogue (empty / particle / ellipsis).

    Soft-AV Qwen batch pads often contaminate a neighbor island into 「は」/「…」
    while the same PCM solo-transcribes correctly (DLDSS-553 迎えにいっちゃう).
    Empty or ellipsis-only text on an island shorter than
    ``_EMPTY_ISLAND_SOLO_MIN_S`` is a breath, not a dropped line.
    """
    raw = str(text or "").strip()
    span = max(0.0, float(span_s or 0.0))
    bare = re.sub(r"[。．.!！?？、,\s…·・♪\[\]]+", "", raw)
    if not raw or not bare:
        return span >= _EMPTY_ISLAND_SOLO_MIN_S
    # Long islands with almost no lexical content are almost always batch miss.
    if span >= 1.2 and len(bare) <= 2:
        return True
    if span >= 2.5 and len(bare) <= 4 and _WEAK_PARTICLE_RE.fullmatch(bare):
        return True
    if bare in {"は", "が", "を", "ん", "あ", "う", "っ"} and span >= 0.8:
        return True
    return False


def _island_transcript_looks_truncated(
    text: str,
    *,
    span_s: float,
    speech_span_n: int = 0,
) -> bool:
    """True when a long multi-span island likely lost mid/late turns.

    Tightened vs early soft-AV heuristics: require ``span >= 4s`` and at least
    two PCM speech spans. Short-but-valid lines on a single continuous
    utterance must not trip half/solo retry (speed + false truncate).
    """
    span = max(0.0, float(span_s or 0.0))
    if span < 4.0:
        return False
    if int(speech_span_n or 0) < 2:
        return False
    bare = re.sub(
        r"[。．.!！?？、,\s…·・♪\[\]]+",
        "",
        str(text or "").strip(),
    )
    if not bare:
        return True
    # Soft-AV ~4–6s multi-pause islands: name-call alone is short while mix
    # energy still has おかえり / 迎え ahead (DLDSS-553).
    min_chars = max(10, int(span * 2.2))
    return len(bare) < min_chars


def _bare_transcript(text: str) -> str:
    return re.sub(r"[。．.!！?？、,\s…·・♪\[\]]+", "", str(text or "").strip())


def _island_looks_like_moan_sfx(text: str) -> bool:
    """True for breath/moan islands — do not spend truncated solo-retry here."""
    bare = _bare_transcript(text)
    if not bare:
        return False
    moan_n = sum(1 for ch in bare if ch in _MOAN_CHARS)
    kanji_n = len(_KANJI_RE.findall(bare))
    if moan_n / max(1, len(bare)) >= 0.55 and kanji_n <= 2:
        return True
    return False


def _island_looks_like_spoken_dialogue(text: str) -> bool:
    """Interview / turn-taking JA (not moan SFX)."""
    raw = str(text or "").strip()
    if not raw:
        return False
    if _DIALOGUE_RE.search(raw):
        return True
    bare = _bare_transcript(raw)
    kanji_n = len(_KANJI_RE.findall(bare))
    if kanji_n >= 2 and not _island_looks_like_moan_sfx(raw):
        return True
    return False


def _ends_with_hesitation_filler(text: str) -> bool:
    bare = _bare_transcript(text)
    return bool(bare) and bool(_FILLER_TAIL_RE.search(bare))


def _transcript_looks_like_hallucination(text: str) -> bool:
    return bool(_HALLU_RE.search(str(text or "")))


def _should_solo_retry_island(
    text: str,
    *,
    span_s: float,
    speech_span_n: int = 0,
) -> bool:
    """Weak always; truncated/filler only when the island is not moan-SFX.

    Soft-AV batch often keeps the first turn (「東北出身で、えー…」) and drops
    the next PCM span on the same FireRed island (self-intro cm/cup, おかえり
    + 迎え). Full truncated retry on moan islands caused loop hallucinations,
    so those stay weak-only.
    """
    weak, truncated = _island_needs_asr_retry(
        text, span_s=span_s, speech_span_n=speech_span_n
    )
    if weak:
        return True
    if _island_looks_like_moan_sfx(text):
        return False
    if truncated:
        return True
    span = max(0.0, float(span_s or 0.0))
    if (
        _ends_with_hesitation_filler(text)
        and span >= 2.2
        and int(speech_span_n or 0) >= 2
        and _island_looks_like_spoken_dialogue(text)
    ):
        return True
    return False


def _uncovered_speech_spans(
    cues: list[dict[str, Any]],
    speech_spans: list[tuple[float, float]] | None,
    *,
    min_dur_s: float = 0.8,
    overlap_s: float = 0.25,
) -> list[tuple[float, float]]:
    """PCM subspans that received almost no painted cue time."""
    if not speech_spans:
        return []
    covered = [
        (float(c.get("start") or 0.0), float(c.get("end") or 0.0))
        for c in (cues or [])
    ]
    out: list[tuple[float, float]] = []
    for a, b in speech_spans:
        dur = float(b) - float(a)
        if dur < float(min_dur_s):
            continue
        ov = 0.0
        for cs, ce in covered:
            ov += max(0.0, min(float(b), ce) - max(float(a), cs))
        if ov < float(overlap_s):
            out.append((float(a), float(b)))
    return out


def _pcm_item_slice(
    item: Any,
    island_start: float,
    span_start: float,
    span_end: float,
) -> Any:
    if not item or not isinstance(item, (tuple, list)) or len(item) < 2:
        return None
    try:
        import numpy as np

        clip = np.asarray(item[0], dtype=np.float32).reshape(-1)
        sr = max(1000, int(item[1] or _QWEN_SR))
        i0 = max(0, int(round((float(span_start) - float(island_start)) * sr)))
        i1 = min(clip.size, int(round((float(span_end) - float(island_start)) * sr)))
        if i1 - i0 < int(0.35 * sr):
            return None
        return (clip[i0:i1], sr)
    except Exception:
        return None


def _island_needs_asr_retry(
    text: str,
    *,
    span_s: float,
    speech_span_n: int = 0,
) -> tuple[bool, bool]:
    """Return ``(weak, truncated)``.

    Callers should use ``_should_solo_retry_island``: weak always retries;
    truncated retries only for spoken dialogue (moan/SFX islands stay weak-only
    — FTHTD-227 loop risk).
    """
    weak = _island_transcript_looks_weak(text, span_s=span_s)
    truncated = (not weak) and _island_transcript_looks_truncated(
        text, span_s=span_s, speech_span_n=speech_span_n
    )
    return weak, truncated


def _frames_sorted_by_duration(
    frames: list[tuple[float, float, Any]],
) -> list[tuple[float, float, Any]]:
    """Group similar-length islands for batching (optional helper; unused by default)."""
    return sorted(
        frames,
        key=lambda fr: (
            max(0.0, float(fr[1]) - float(fr[0])),
            float(fr[0]),
        ),
    )


def _sort_cues_by_start(cues: list[dict[str, Any]]) -> list[dict[str, Any]]:
    return sorted(
        cues,
        key=lambda c: (
            float(c.get("start") or 0.0),
            float(c.get("end") or 0.0),
        ),
    )


def _pcm_halves(item: Any) -> list[Any]:
    """Split island PCM tuple into two overlapping halves (legacy truncate-retry)."""
    if not item or not isinstance(item, (tuple, list)) or len(item) < 2:
        return []
    try:
        import numpy as np

        clip = np.asarray(item[0], dtype=np.float32).reshape(-1)
        sr = max(1000, int(item[1] or _QWEN_SR))
        if clip.size < int(1.2 * sr):
            return []
        mid = clip.size // 2
        overlap = int(0.25 * sr)
        left = clip[: max(mid + overlap, int(0.6 * sr))]
        right = clip[max(0, mid - overlap) :]
        if left.size < int(0.4 * sr) or right.size < int(0.4 * sr):
            return []
        return [(left, sr), (right, sr)]
    except Exception:
        return []


def _solo_retry_weak_island_result(
    *,
    active_model: Any,
    item: Any,
    result: Any,
    lang: str | None,
    want_ts: bool,
    start: float,
    end: float,
    label: str,
    speech_span_n: int = 0,
) -> tuple[Any, str | None]:
    """Re-ASR one island when empty/trivial, truncated dialogue, or filler-tail.

    Returns ``(result, kind)`` with ``kind`` ``None`` or ``\"solo\"``.
    Moan-SFX truncated islands stay weak-only (loop risk).
    Cue timing still uses the original island + PCM speech spans.
    """
    span = max(0.1, float(end) - float(start))
    text = _result_text(result)
    if item is None or not _should_solo_retry_island(
        text, span_s=span, speech_span_n=speech_span_n
    ):
        return result, None
    try:
        solo = _transcribe_audio_list(
            active_model,
            [item],
            lang,
            want_ts=want_ts,
            max_new_tokens=(None if want_ts else _ISLAND_MAX_NEW_TOKENS),
        )
        if not solo:
            return result, None
        solo_text = _result_text(solo[0])
        if _island_transcript_looks_weak(solo_text, span_s=span):
            return result, None
        if _transcript_looks_like_hallucination(solo_text):
            return result, None
        orig_n = len(_bare_transcript(text))
        solo_n = len(_bare_transcript(solo_text))
        orig_weak = _island_transcript_looks_weak(text, span_s=span)
        if solo_n < orig_n and not orig_weak:
            return result, None
        return solo[0], "solo"
    except Exception as err:
        _log.debug(
            "Qwen %s solo-retry island %.2f-%.2fs failed: %s",
            label,
            float(start),
            float(end),
            err,
        )
        return result, None


def _retry_uncovered_speech_spans(
    *,
    active_model: Any,
    item: Any,
    lang: str | None,
    want_ts: bool,
    island_start: float,
    cues: list[dict[str, Any]],
    speech_spans: list[tuple[float, float]] | None,
    label: str,
    max_spans: int = 2,
) -> list[dict[str, Any]]:
    """Solo-ASR leftover PCM spans on a lexical island (batch painted only the first turn)."""
    leftover = _uncovered_speech_spans(cues, speech_spans)[: max(0, int(max_spans))]
    if not leftover or item is None:
        return []
    extra: list[dict[str, Any]] = []
    for a, b in leftover:
        span = max(0.1, float(b) - float(a))
        if span < 0.55:
            continue
        slice_item = _pcm_item_slice(item, island_start, a, b)
        if slice_item is None:
            continue
        try:
            solo = _transcribe_audio_list(
                active_model,
                [slice_item],
                lang,
                want_ts=want_ts,
                max_new_tokens=(None if want_ts else _ISLAND_MAX_NEW_TOKENS),
            )
        except Exception as err:
            _log.debug(
                "Qwen %s leftover-span %.2f-%.2fs failed: %s",
                label,
                a,
                b,
                err,
            )
            continue
        if not solo:
            continue
        text = _normalize_filler_no(_result_text(solo[0]))
        span = max(0.1, float(b) - float(a))
        if _island_transcript_looks_weak(text, span_s=span):
            continue
        if _transcript_looks_like_hallucination(text):
            continue
        if _island_looks_like_moan_sfx(text):
            continue
        if _cue_text_is_measure_shard(text):
            continue
        if any(
            _cue_text_is_echo(text, str(c.get("text") or ""))
            for c in (list(cues or []) + extra)
        ):
            continue
        # Sub-second leftover slices are almost always echo shards, not new turns.
        if span < 0.62 and len(re.sub(r"\s+", "", text or "")) <= 8:
            continue
        extra.extend(
            _distribute_text_cues(
                text,
                start=float(a),
                end=float(b),
                speech_spans=[(float(a), float(b))],
            )
        )
    return extra
